\section{Introduction}

Trial division tests candidates $d\le\sqrt N$ until one divides $N$. For a semiprime
$N=pq$ with $p\le q$, the pool $\{2,\dots,\fsq\}$ contains exactly one divisor, $p$. Every
earlier test is overhead. There are two classical ways to cut that overhead.

\emph{Filtering by residue} keeps only candidates in chosen residue classes modulo some $M$.
A previously established theorem, the \emph{residue cap}, shows that no such filter improves
the expected number of tests by more than $4/3$, whatever its modulus and retained classes.
The reason is that the residue of the hidden prime is uniformly distributed.

\emph{Reordering by position} keeps the pool and changes the order. Fermat's method starts at
$\sqrt N$ because balanced factors lie near $\sqrt N$. We apply the same order to
divisibility tests.

A guess made before measurement held that positional gains would stay below $2\times$. A
sham-controlled experiment refuted it, measuring $5.19\times$. This paper supplies the
mathematics behind that measurement. All costs count divisibility tests, which measure
information, not wall-clock time.

\section{The finite model and exact costs}

\begin{definition}[Pool, order, cost]
The standard pool of $N$ is $\mathcal P(N)=\{2,\dots,\fsq\}$. A visitation order is a key
$\kappa:\mathbb N\to\mathbb N$, and candidates are tested in increasing key order. The scan
cost on a pool $P$ is
\[
\mathrm{cost}_P(\kappa,N)=\#\{d\in P:\ \kappa(d)\le\kappa(e)\ \text{for all } e\in P
\text{ with } e\mid N\}.
\]
The ascending order is $\kappa(d)=d$ (cost $\asc(N)$). The sqrt-descending order is
$\kappa(d)=N-d$ (cost $\desc(N)$).
\end{definition}

\begin{lemma}[Unique hit]\label{lem:unique}
For primes $p\le q$, the only divisor of $pq$ in $\mathcal P(pq)$ is $p$, and $p\in\mathcal
P(pq)$.
\end{lemma}
\begin{proof}
$p^2\le pq$ gives $p\le\lfloor\sqrt{pq}\rfloor$. A divisor $d\ge2$ is $p$, $q$ or $pq$. The
value $pq$ is too large, and $q$ in the pool forces $q^2\le pq$, hence $q=p$.
\end{proof}

\begin{theorem}[Exact costs; complementarity]\label{thm:costs}
For primes $p\le q$ and $N=pq$:
$\asc(N)=p-1$, $\desc(N)=\fsq+1-p$, and $\asc(N)+\desc(N)=\fsq$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:unique} the cost is the number of pool elements whose key is at most that
of $p$. These are $\{2,\dots,p\}$ for the ascending key and $\{p,\dots,\fsq\}$ for the
descending key.
\end{proof}

\begin{example}
For $N=101\cdot103$ we have $\fsq=101$. The ascending scan pays $100$ tests and the
descending scan pays $1$.
\end{example}

\begin{theorem}[Balance wall at $4$]\label{thm:wall}
Let $p\le q$ be primes. If $q<4p$, then $\desc(pq)\le\asc(pq)+1$. If $q\ge4p$, then
$\asc(pq)+2\le\desc(pq)$.
\end{theorem}
\begin{proof}
$pq<(2p)^2$ gives $\lfloor\sqrt{pq}\rfloor\le2p-1$, hence $\desc\le p$. Conversely,
$pq\ge(2p)^2$ gives $\lfloor\sqrt{pq}\rfloor\ge2p$, hence $\desc\ge p+1$.
\end{proof}

\begin{theorem}[Near-squares are cheap]\label{thm:gap}
For primes $p\le q$, $2(\desc(pq)-1)\le q-p$. In particular $q\le p+3$ implies
$\desc(pq)\le2$.
\end{theorem}
\begin{proof}
Floor AM--GM gives $2\lfloor\sqrt{pq}\rfloor\le p+q$. Otherwise $4pq\ge4s^2>(p+q)^2$, which
contradicts $(p-q)^2\ge0$. Then $\desc-1=\lfloor\sqrt{pq}\rfloor-p\le(q-p)/2$.
\end{proof}

\begin{theorem}[Fermat--trial complementarity]\label{thm:fermat}
For primes $p\le q$,
\[
\desc(pq)+\Bigl(\Bigl\lfloor\tfrac{p+q}{2}\Bigr\rfloor-\lfloor\sqrt{pq}\rfloor\Bigr)
=\Bigl\lfloor\tfrac{q-p}{2}\Bigr\rfloor+1.
\]
\end{theorem}
\begin{proof}
Substitute Theorem~\ref{thm:costs}. Since $p\le\lfloor\sqrt{pq}\rfloor\le(p+q)/2$, the square
roots cancel, leaving $\lfloor(p+q)/2\rfloor-p+1=\lfloor(q-p)/2\rfloor+1$.
\end{proof}

\begin{remark}
For odd primes, $a=(p+q)/2$ is where Fermat's upward walk succeeds, since
$N=a^2-((q-p)/2)^2$. The descending scan walks $\fsq\downarrow p$ and Fermat walks
$\fsq\uparrow a$. Together they cover $[p,a]$ exactly once.
\end{remark}

\section{The speedup law}

\begin{definition}
For $r>1$ the positional speedup is $S(r)=1/(\sqrt r-1)$.
\end{definition}

\begin{theorem}[The law]\label{thm:law}
For real $0<p<q$, $\dfrac{p}{\sqrt{pq}-p}=S(q/p)$.
\end{theorem}
\begin{proof}
$\sqrt{pq}=p\sqrt{q/p}$, so $\sqrt{pq}-p=p(\sqrt{q/p}-1)\neq0$. Cancel $p$.
\end{proof}

\begin{theorem}[Balance windows]\label{thm:window}
For $r>1$ and $k>0$: $k<S(r)\iff r<(1+1/k)^2$, and $k\le S(r)\iff r\le(1+1/k)^2$.
\end{theorem}
\begin{proof}
Multiply by $\sqrt r-1>0$ to get $k\sqrt r<k+1$, that is $\sqrt r<1+1/k$. Square both
positive sides.
\end{proof}

\begin{center}
\begin{tabular}{@{}lcccccc@{}}
\toprule
threshold $k$ & $4/3$ & $2$ & $5.19$ & $10$ & $20.67$\\
window edge $(1+1/k)^2$ & $49/16$ & $2.25$ & $\approx1.4225$ & $1.21$ & $\approx1.0991$\\
\bottomrule
\end{tabular}
\end{center}

\begin{theorem}[Monotonicity and unboundedness]\label{thm:mono}
$S$ is strictly decreasing on $(1,\infty)$, and for every real $k$ there is $r>1$ with
$S(r)>k$.
\end{theorem}
\begin{proof}
$\sqrt r-1$ is positive and strictly increasing. For the second claim take $m=\max(k,1)$
and $r=(1+\frac1{2m})^2$. Theorem~\ref{thm:window} gives $S(r)\ge2m>k$.
\end{proof}

\begin{proposition}[Special values]\label{prop:values}
$S(5/4)=4+2\sqrt5$, $S(2)=1+\sqrt2$, $S(49/16)=4/3$ and $S(4)=1$.
\end{proposition}
\begin{proof}
$1/(\sqrt5/2-1)=2(\sqrt5+2)$. Next, $1/(\sqrt2-1)=\sqrt2+1$. Finally $\sqrt{49/16}=7/4$ and
$\sqrt4=2$.
\end{proof}

\section{The barrier map}

\begin{definition}[Residue dial]
A residue dial $(M,K)$ fixes a modulus $M\ge1$ and a set $K$ of unit classes modulo $M$, and
tests only candidates whose residue lies in $K$. Its speedup is measured under a uniform
distribution of the hidden prime's residue over unit classes. The \emph{residue cap} is the
established theorem that every residue dial has speedup at most $4/3$.
\end{definition}

\begin{theorem}[Barrier map]\label{thm:barrier}
\begin{enumerate}
\item For $1<r<49/16$ and every residue dial $(M,K)$, the dial's speedup is strictly less
than $S(r)$.
\item $S(49/16)=4/3$, and $S(r)\le4/3$ for all $r\ge49/16$.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) Theorem~\ref{thm:window} with $k=4/3$ gives $S(r)>4/3$ if and only if
$r<(7/4)^2=49/16$. Combine this with the residue cap. (2) Use Proposition~\ref{prop:values}
and Theorem~\ref{thm:mono}.
\end{proof}

\section{Why position escapes the residue cap}

Let there be $n=m+1$ candidates with target weights $\mu_i\in\mathbb R$. An order is a
permutation $\sigma$, and candidate $i$ is tested at step $\sigma(i)+1$.

\begin{definition}[Order cost, sham, cyclic shift]
$C_\mu(\sigma)=\sum_i\mu_i(\sigma(i)+1)$ and
$\Sham(\mu)=\bigl(\sum_i\mu_i\bigr)\frac{n+1}{2}$. For $k\in\mathbb Z/n$, the cyclic shift
is $\sigma_k(i)=\sigma(i)+k\bmod n$.
\end{definition}

\begin{lemma}[Uniform-marginal lemma]\label{lem:uniform}
If $\mu$ is constant, then $C_\mu(\sigma)=\Sham(\mu)$ for all $\sigma$.
\end{lemma}
\begin{proof}
$\sum_i(\sigma(i)+1)=n(n+1)/2$ for every permutation.
\end{proof}

\begin{lemma}[Cyclic sham]\label{lem:sham}
$\sum_{k\in\mathbb Z/n}C_\mu(\sigma_k)=n\,\Sham(\mu)$ for all $\mu$ and $\sigma$.
\end{lemma}
\begin{proof}
For fixed $i$, as $k$ varies the position $\sigma(i)+k$ runs over all of $\mathbb Z/n$.
\end{proof}

\begin{lemma}[Discrete derivative]\label{lem:deriv}
$C_\mu(\sigma_{k+1})-C_\mu(\sigma_k)=\sum_i\mu_i-n\,\mu_{\sigma^{-1}(m-k)}$.
\end{lemma}
\begin{proof}
Each position rises by one, except the candidate at position $m$, which wraps to $0$.
\end{proof}

\begin{theorem}[Separation theorem]\label{thm:sep}
Some order $\sigma$ has $C_\mu(\sigma)<\Sham(\mu)$ if and only if $\mu$ is not constant.
Moreover, if $\mu$ is not constant, then every order has a cyclic shift that strictly beats
the sham.
\end{theorem}
\begin{proof}
If $\mu$ is constant, apply Lemma~\ref{lem:uniform}. Otherwise, suppose every shift costs at
least the sham. By Lemma~\ref{lem:sham} all shifts then cost exactly the sham, and
Lemma~\ref{lem:deriv} forces $n\mu_i=\sum_j\mu_j$ for every $i$, a contradiction.
\end{proof}

\begin{remark}
Residue filters act on a uniform marginal (Lemma~\ref{lem:uniform}), which is the source of
the $4/3$ cap. A balance-concentrated ensemble induces a marginal over positions that is
skewed towards $\sqrt N$ (Theorem~\ref{thm:sep}). The two results lie on opposite sides of
this equivalence.
\end{remark}

\begin{theorem}[Bayes order]\label{thm:bayes}
If $\sigma(i)<\sigma(j)\Rightarrow\mu_i\ge\mu_j$, then $C_\mu(\sigma)\le C_\mu(\tau)$ for
every order $\tau$.
\end{theorem}
\begin{proof}
This is the rearrangement inequality.
\end{proof}

\begin{theorem}[Fermat's order is Bayes]\label{thm:fermatbayes}
Index the pool from smallest to largest. If $\mu$ is nondecreasing, then the reversal order
(sqrt-descending) minimises $C_\mu$. If $\mu$ is nonincreasing, the ascending order does.
If $n\ge2$ and $\mu$ is strictly increasing, the descending order strictly beats the sham.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:bayes}. For strictness, combine it with Theorem~\ref{thm:sep}.
\end{proof}

\section{Two mechanisms, opposite gradients}

If every prime lies below $B=2^{17}$, then $p>N/B$. The magnitude of $N$ therefore reveals a
lower bound $L\le p$. Let $\mathcal P_L(N)=\{\max(2,L),\dots,\fsq\}$.

\begin{theorem}[Orthogonality]\label{thm:orth}
For primes $p\le q$ and $2\le L\le p$, the ascending scan of $\mathcal P_L$ costs
$p+1-L=\asc(pq)-(L-2)$, and the descending scan of $\mathcal P_L$ costs exactly $\desc(pq)$.
\end{theorem}
\begin{proof}
$p$ remains the unique hit. The ascending scan visits $\{L,\dots,p\}$, while the descending
scan visits $\{p,\dots,\fsq\}$ as before.
\end{proof}

\begin{theorem}[Stratum bands]\label{thm:bands}
If $1<r\le5/4$, then $S(r)\ge4+2\sqrt5$. If $5/4\le r\le2$, then
$1+\sqrt2\le S(r)\le4+2\sqrt5$. If $2\le r\le4$, then $1\le S(r)\le1+\sqrt2$.
\end{theorem}
\begin{proof}
Use Theorem~\ref{thm:mono} and Proposition~\ref{prop:values}.
\end{proof}

\begin{lemma}[Mediant principle]\label{lem:mediant}
If $s$ is finite and nonempty, $b_i>0$, and $Lb_i\le a_i\le Ub_i$ for all $i\in s$, then
$L\le\sum a_i/\sum b_i\le U$.
\end{lemma}

\begin{theorem}[Band for expected speedups]\label{thm:expband}
If $(p_i,q_i)_{i\in s}$ are positive reals with $r_1p_i\le q_i\le r_2p_i$ and $1<r_1$, then
\[
S(r_2)\le\frac{\sum_ip_i}{\sum_i(\sqrt{p_iq_i}-p_i)}\le S(r_1).
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:law}, $p_i=S(q_i/p_i)(\sqrt{p_iq_i}-p_i)$. Bound $S(q_i/p_i)$ by
monotonicity and apply Lemma~\ref{lem:mediant}.
\end{proof}

\begin{corollary}[Consistency of the measurement]
$4+2\sqrt5\le20.67$, $1+\sqrt2\le4.74\le4+2\sqrt5$, $1\le1.97\le1+\sqrt2$, and
$1+\sqrt2>4/3$.
\end{corollary}

\section{The experiment}

The ensemble consisted of semiprimes with prime factors below $2^{17}$, with $30{,}000$
instances in each of $5$ batches and a fixed seed. The sqrt-descending order gave an expected
speedup of $5.1936\times$. The sham, the average of cyclic shifts of real orders
(Lemma~\ref{lem:sham}), gave $1.65\times$, so real/sham $=3.16$.

\begin{center}
\begin{tabular}{@{}lccc@{}}
\toprule
mechanism & $q/p\in[1,1.25]$ & $[1.25,2]$ & $[2,4]$\\
\midrule
(a) balance bet & $20.67\times$ & $4.74\times$ & $1.97\times$\\
(b) range truncation ($p\ge N/2^{17}$) & $4.35\times$ & $4.73\times$ & $6.91\times$\\
\bottomrule
\end{tabular}
\end{center}

A learned Bayes ordering scored $3.37\times$ on test data. Its apparent edge over plain
sqrt-descending came from the training data, so the honest computable frontier is plain
sqrt-descending. The same experiment refuted a claim that the smooth posterior collapses at
the pool's truncation edge, while a designed degenerate-order check passed $30000/30000$.
The experiment's ledger records seven entries, including one self-refutation by a learned
model and one feature found to be vacuous.

\section{Algorithms}

\begin{algorithm}[Sqrt-descending trial division]
For $d=\fsq,\fsq-1,\dots,2$: if $d\mid N$, return $d$. On a semiprime this uses
$\fsq+1-p\le(q-p)/2+1$ tests.
\end{algorithm}

\begin{algorithm}[Truncated scan]
Given a certified $L\le p$, scan $\{\max(2,L),\dots,\fsq\}$. The ascending scan costs
$p+1-L$ and the descending scan is unchanged.
\end{algorithm}

\begin{algorithm}[Bayes order and sham]
Visit candidates in decreasing prior weight. For the sham, draw $k\in\mathbb Z/n$ uniformly
and use $\sigma_k$, whose expected cost is $\Sham(\mu)$.
\end{algorithm}

\section{Discussion and future work}

Residue information is capped at $4/3$ under a uniform marginal. Positional information obeys
$S(r)=1/(\sqrt r-1)$ and is unbounded at near-squares. The two meet at $r=49/16$, and they
are separated exactly by the scope of the uniform-marginal lemma. All statements concern test
counts within trial division, not the hardness of factoring properly generated moduli.

\begin{enumerate}
\item \emph{Optimal interleaved schedule.} Alternate descending steps from $\fsq$ with
ascending steps from $L$ in a ratio $\lambda:1$. We conjecture that the best $\lambda$ beats
both pure orders, by at least $1.3\times5.19$ on the experimental ensemble.
\item \emph{Fermat walk duality.} By Theorem~\ref{thm:fermat},
$\min(\desc,\mathrm{fermat})\le\frac12\bigl(\lfloor\frac{q-p}2\rfloor+1\bigr)$. We conjecture
that Fermat wins on $q/p\in[1,1.25]$ for all but an $O(1/\sqrt p)$ fraction of instances.
\item \emph{Prime-only pools}, where the analogue of $S(r)$ involves
$\pi(\sqrt N)-\pi(p)$.
\item \emph{Joint residue--position filters} and a product law for their speedups.
\end{enumerate}

