import math

def sqrt_descending_trial_division(n: int) -> tuple[int | None, int]:
    """Return (smallest-found divisor or None, number of divisibility tests).

    Visits d = floor(sqrt n), floor(sqrt n) - 1, ..., 2.  On a semiprime n = p q with
    primes p <= q it returns p after exactly floor(sqrt n) + 1 - p tests, which is
    at most (q - p)/2 + 1.
    """
    tests = 0
    for d in range(math.isqrt(n), 1, -1):
        tests += 1
        if n % d == 0:
            return d, tests
    return None, tests

def ascending_trial_division(n: int) -> tuple[int | None, int]:
    tests = 0
    for d in range(2, math.isqrt(n) + 1):
        tests += 1
        if n % d == 0:
            return d, tests
    return None, tests

if __name__ == "__main__":
    for p, q in [(101, 103), (1009, 1013), (101, 401), (7, 9973)]:
        n = p * q
        print(n, ascending_trial_division(n), sqrt_descending_trial_division(n))
